#!/usr/bin/env bash
# Generate the Codex agent TOMLs from the canonical role agents. Codex is the
# one harness that defines agents in TOML instead of markdown, so this is the
# only generated file set in the repository. Skills need no generation:
# .agents/skills is read natively by Codex, Copilot, and OpenCode, and by
# Claude Code through the committed plugin (.claude-plugin/plugin.json).
#
# Canonical (edit these):
#   .claude/agents/<name>.md         read natively by Claude Code, Copilot;
#                                    OpenCode through opencode.json pointers
# Generated (committed, never edited by hand):
#   .codex/agents/<name>.toml        built from .claude/agents
# Last verified: 2026-09. Evidence: docs/research/shared-ai-resources-without-symlinks.md
#
# Usage:
#   scripts/sync.sh           rewrite .codex/agents from .claude/agents
#   scripts/sync.sh --check   exit 1 if .codex/agents is stale or an agent's
#                             description is missing from opencode.json (CI runs this)
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
agents_src="$root/.claude/agents"
mirrors=(".codex/agents")
check=0

case "${1:-}" in
  "") ;;
  --check) check=1 ;;
  -h|--help) sed -n '2,18p' "$0"; exit 0 ;;
  *) echo "unknown flag: $1 (see --help)" >&2; exit 2 ;;
esac

[ -d "$agents_src" ] || { echo ".claude/agents not found at $agents_src" >&2; exit 1; }

toml_escape() {
  sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

# Line number of the closing --- of the frontmatter; empty if never closed.
frontmatter_end() {
  awk 'NR > 1 && /^---[[:space:]]*$/ {print NR; exit}' "$1"
}

# The description: value from the frontmatter; empty if absent.
description_of() {
  local closing
  closing="$(frontmatter_end "$1")"
  [ -n "$closing" ] || return 0
  awk -v end="$closing" 'NR > 1 && NR < end' "$1" | sed -n 's/^description:[[:space:]]*//p' | head -n 1
}

# Codex defines agents in TOML: name, description, developer_instructions.
write_codex_toml() {
  local agent_md="$1" name="$2" out="$3" closing desc body
  closing="$(frontmatter_end "$agent_md")"
  desc="$(description_of "$agent_md")"
  body=""
  [ -z "$closing" ] || body="$(awk -v start="$closing" 'NR > start' "$agent_md")"
  [ -n "$desc" ] || desc="$name agent (see .claude/agents/$name.md)"
  {
    printf '# Generated by scripts/sync.sh from .claude/agents/%s.md. Do not edit.\n' "$name"
    printf 'name = "%s"\n' "$name"
    printf 'description = "%s"\n' "$(printf '%s' "$desc" | toml_escape)"
    printf 'developer_instructions = """\n'
    printf '%s\n' "$body" | toml_escape
    printf '"""\n'
  } > "$out"
}

# Build the generated files under $1, laid out exactly as in the repository.
build() {
  local dest="$1" agent_md name
  mkdir -p "$dest/.codex/agents"

  for agent_md in "$agents_src"/*.md; do
    [ -f "$agent_md" ] || continue
    if ! head -n 1 "$agent_md" | grep -qx -- '---'; then
      echo "no frontmatter: ${agent_md#"$root"/}" >&2
      exit 1
    fi
    name="$(basename "$agent_md" .md)"
    write_codex_toml "$agent_md" "$name" "$dest/.codex/agents/$name.toml"
  done
}

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
build "$tmp"

if [ "$check" -eq 1 ]; then
  [ -f "$root/opencode.json" ] || { echo "opencode.json not found at $root/opencode.json" >&2; exit 1; }
  stale=0
  for m in "${mirrors[@]}"; do
    if ! diff -rq -x .DS_Store "$tmp/$m" "$root/$m" >&2; then
      printf 'STALE %s\n' "$m" >&2
      stale=$((stale + 1))
    fi
  done
  # OpenCode reads each agent through an opencode.json pointer whose
  # description is repeated by hand, so check it still matches the frontmatter.
  for agent_md in "$agents_src"/*.md; do
    [ -f "$agent_md" ] || continue
    name="$(basename "$agent_md" .md)"
    desc="$(description_of "$agent_md")"
    if [ -z "$desc" ] || ! grep -qF -- "$desc" "$root/opencode.json"; then
      printf 'STALE opencode.json: %s description\n' "$name" >&2
      stale=$((stale + 1))
    fi
  done
  if [ "$stale" -gt 0 ]; then
    echo "generated files are out of date: edit .claude/agents and opencode.json together, then run 'make sync' and commit" >&2
    exit 1
  fi
  echo "OK: .codex/agents and opencode.json match .claude/agents"
  exit 0
fi

for m in "${mirrors[@]}"; do
  rm -rf "${root:?}/$m"
  mkdir -p "$(dirname "$root/$m")"
  cp -R "$tmp/$m" "$root/$m"
  printf 'synced %s\n' "$m"
done
